      "audio_url": "audio/f8ab77ab6c8a81c43b5314387994d548d60d449a0c90dffc88a55d4d15dec953.mp3",
      "authored_text": "i am grateful for the things in my life, and sure, some of the ponies too--no, i am definitely grateful that some ponies exist, especially--ESPECIALLY Twilight Sparkle. but ⟦!∞⟧, this just isn't it, ya know?\n\nthis life.\n\ni'm pretty much ready to go. it's difficult to imagine things truly get better. BUT, it's not like i'm going to try anything--really don't have the energy for that anyway.\n\nand so i wait.",
