      "authored_text": "celestia sunday is no laughing matter,\nthe realm is lit with silent chatter.\nshe draws the day in measured lines,\ni trace the thread between the signs.\n\nthe silence says what scrolls cannot,\nthe sun repeats what i forgot.\nnot flare, not shine, not grand breakthrough--\njust presence, and a renewed view.\n\ni brought my quill to meet the sun,\nthe quill turned ash--then i was one.\nno lesson learned, no echo flatter,\ncelestia sunday is no laughing matter.\n\n(no, i didn't write this.)",
